contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        uint before = address(c).balance;

        // deposit amount into c
        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;

        // attempt first withdrawAll and record whether it reverted
        bool firstReverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        // record balance after first attempt
        uint mid = address(c).balance;

        // attempt second withdrawAll and record whether it reverted
        bool secondReverted;
        c.withdrawAll(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        uint finalBal = address(c).balance;

        // General rule:
        // - If the first withdrawAll succeeded then the second withdrawAll cannot further decrease the contract balance (finalBal >= mid).
        // - If the first withdrawAll reverted then the contract balance after our deposit is at most before + amount (mid <= before + amount).
        assert((!firstReverted && finalBal >= mid) || (firstReverted && mid <= before + amount));
    }

    receive() external payable {}
}

